import torch.nn as nn

class RedeSimples(nn.Module):
    def __init__(self):
        super().__init__()
        self.camada1 = nn.Linear(10, 64)
        self.relu = nn.ReLU()
        self.saida = nn.Linear(64, 2)

    def forward(self, x):
        return self.saida(self.relu(self.camada1(x)))

